uint32_t vertrix_lift_count(void)
{
    return (uint32_t)(sizeof(routines) / sizeof(routines[0]));
}

VertrixLiftFunction vertrix_lift_find(uint32_t address)
{
    uint32_t low = 0;
    uint32_t high = vertrix_lift_count();
    while (low < high)
    {
        uint32_t middle = (low + high) / 2;
        if (routines[middle].address == address)
        {
            return routines[middle].function;
        }
        if (routines[middle].address < address)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    return NULL;
}
